from hashlib import sha256 as CalcSha

from convert.adapters.solidworks.Archive.Construction.Ellipse.EllipsePart import (
    EllipsePart,
)
from convert.adapters.solidworks.Archive.Header.ReadFileTable import GetFileRef
from convert.adapters.solidworks.Archive.Header.ReadNativeHeader import ReadHeaderGraph
from convert.adapters.solidworks.Core.Writing.Measured.ReadMeasRows import ReadMeasRows


# the complete regenerated bytes must have one case with the same authored clock and locator
def MatchEllipCase(
    Receipt: dict[str, object], Candidate: EllipsePart, WrittenAt: int
) -> dict[str, object]:
    Digest = CalcSha(Candidate.BytesValue).hexdigest()
    Cases = ReadMeasRows(Receipt.get("cases"), 32)
    Matches = tuple(
        CaseValue for CaseValue in Cases if CaseValue.get("archive_sha256") == Digest
    )
    if len(Matches) != 1:
        raise ValueError(
            "regenerated SOLIDWORKS ellipse has no unique exact native measurement"
        )
    (CaseValue,) = Matches
    HeaderValue = ReadHeaderGraph(
        Candidate.StreamsValue["Contents/Config-0-ModelHeader"],
        Candidate.ConfigValue.VersionValue,
    )
    SelfValue = GetFileRef(HeaderValue.FieldsValue["f38"])
    SlotId = CaseValue.get("slot")
    if (
        type(SlotId) is not int
        or not 0 <= SlotId < len(Cases)
        or type(CaseValue.get("written_at")) is not int
        or WrittenAt != CaseValue["written_at"]
        or type(CaseValue.get("archive_bytes")) is not int
        or len(Candidate.BytesValue) != CaseValue["archive_bytes"]
        or SelfValue.PathValue != CaseValue.get("locator")
    ):
        raise ValueError(
            "ellipse measurement does not match the generated scope or locator"
        )
    return CaseValue
